    input_path = positional[0]
    selector = positional[1]
    # Check input existence
    if input_path != "-" and not pathlib.Path(input_path).exists():
        eprint(f"error: input file not found (searched at {input_path})")
        sys.exit(1)
    # Handle deprecation warning to stderr
    eprint("warning: the `typst query` subcommand is deprecated\n = hint: use `typst eval 'query(<mymeta>)' --in /tmp/typst_query.typ` instead")
    # Actually the hint should reflect the actual selector and input? For generic, we will print the template from original: it used input_path and selector
    # For precise match, original had: `use `typst eval 'query(<mymeta>)' --in /tmp/typst_query.typ` instead  for first case
